  ('933c768d-0304-5023-a9a9-6c7c42c86e44', null, (select id from public.skills where slug = 'read-g12-connections'), null, 'medium',
   $q$How did the examination of the frame respond to Abadi's objection?$q$, $q$[{"text":"It showed the frame was made after 1824, which proved the painting was a later copy.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It showed the dealer's label could have come from another work, weakening his evidence.","is_correct":true},{"text":"It confirmed the label was original, so Abadi's objection was set aside for other reasons.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It showed the dealer had sold forged paintings, so his label could never be trusted.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It showed the dealer's label could have come from another work, weakening his evidence.$q$, $q$Abadi pointed to a 1790s dealer's label, and paragraph 4 says it had been glued onto a newer board, "so it could have been moved from another work." That undercut the label without saying anything about the dealer's honesty.$q$, 'draft', '61d06bc3-f6c7-5207-83b7-199fe7ce9908')
