values
  ('f1b23860-8d95-5902-9804-15ee850cfd6c', null, (select id from public.skills where slug = 'read-g12-connections'), null, 'hard',
   $q$Why was the pigment finding not enough by itself to change the painting's attribution?$q$, $q$[{"text":"The museum's reference records on pigment dates were known to be unreliable.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Abadi refused to accept any evidence that came from a single speck of paint.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Ferrant was known to experiment with new pigments late in his career.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"A restorer might have added the blue later, so other evidence had to rule out a repair.","is_correct":true}]$q$::jsonb, $q$A restorer might have added the blue later, so other evidence had to rule out a repair.$q$, $q$Paragraph 3 shows that a late pigment fits two explanations, including "a later repair," so the sketch evidence was needed to decide. The passage says Ferrant used a costly mineral pigment, not that he experimented with new ones.$q$, 'draft', '61d06bc3-f6c7-5207-83b7-199fe7ce9908')
