values
  ('f3b2c58f-04f8-59f6-b841-974af4d75a8a', null, (select id from public.skills where slug = 'read-g12-figurative-language'), null, 'hard',
   $q$Kwame says, "We saw three meteors. And somehow it was the best shower I've ever been to." How does the passage explain this paradox?$q$, $q$[{"text":"The three meteors were larger than any meteors ever recorded.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Kwame is being sarcastic because the trip disappointed him.","is_correct":false,"misconception_token":"misreads-tone"},{"text":"Kwame miscounted, and the club actually saw hundreds of meteors.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The shared fun and the rare, hard-won glimpse made few meteors precious.","is_correct":true}]$q$::jsonb, $q$The shared fun and the rare, hard-won glimpse made few meteors precious.$q$, $q$The night was filled with invented constellations and laughter, and the brief gap made the three meteors feel rare and earned, so quality outweighed quantity. His quiet, half-to-himself tone and the celebration in the field show he means it sincerely.$q$, 'draft', '644ac0f9-9f8b-5995-bbe1-d02e8ddd4f9b')
