  ('ced37f04-598a-54ee-978f-334a6c56a5ea', null, (select id from public.skills where slug = 'read-g12-literary-structure-pov'), null, 'easy',
   $q$What does the reader understand about the "comet" that the narrator does not?$q$, $q$[{"text":"It is almost certainly a smudge or spot of dirt on the telescope's lens.","is_correct":true},{"text":"It is a trick of the porch light that Funmi set up to fool her brother.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It is a distant planet that only appears during the month of October.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It is a real comet that the observatories will soon confirm and name.","is_correct":false,"misconception_token":"takes-speaker-literally"}]$q$::jsonb, $q$It is almost certainly a smudge or spot of dirt on the telescope's lens.$q$, $q$The spot never moves, appears even on the moon "in the same corner of the view," and vanishes after Funmi uses a cloth, all pointing to a dirty lens. Nothing suggests Funmi planned a trick.$q$, 'draft', '292d4398-3385-5e97-9236-fc0ae5fd6afc')
