  ('fd6a4c98-98d3-5203-8374-aceea7fb4ce5', null, (select id from public.skills where slug = 'read-g12-literary-structure-pov'), null, 'medium',
   $q$Why is the story told as a series of dated journal entries?$q$, $q$[{"text":"The entries let the narrator prove to the observatories exactly when he made his discovery.","is_correct":false,"misconception_token":"confuses-author-speaker"},{"text":"The entries let the author jump backward in time to show how the narrator learned astronomy.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"The entries let several different family members share their views of the comet in turn.","is_correct":false,"misconception_token":"misidentifies-speaker"},{"text":"The entries let clues pile up day by day while the narrator keeps explaining each one away.","is_correct":true}]$q$::jsonb, $q$The entries let clues pile up day by day while the narrator keeps explaining each one away.$q$, $q$Each entry adds evidence (the fixed spot, the moon, the cloth) and a fresh excuse, building dramatic irony. All entries are by the narrator and move forward in time.$q$, 'draft', '292d4398-3385-5e97-9236-fc0ae5fd6afc')
