  ('e8a5ab4a-57e3-53a1-bfab-cb2c5c63c040', null, (select id from public.skills where slug = 'read-g12-literary-structure-pov'), null, 'medium',
   $q$What does the reader know that the girl does not?$q$, $q$[{"text":"That the metronome is broken and has been keeping the wrong time for years","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"That her father practiced this same piece in this room and stumbled at the same spot","is_correct":true},{"text":"That the penciled marks were written by a famous composer long ago","is_correct":false,"misconception_token":"contradicts-text"},{"text":"That her teacher plans to stop giving lessons at the end of the winter","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$That her father practiced this same piece in this room and stumbled at the same spot$q$, $q$The metronome tells us "The girl who sits here doesn't know / her father practiced here before," creating dramatic irony. The marks are her father's, not a composer's.$q$, 'draft', '17f4d92d-1a54-5d2c-9ec9-97ba34d2b3c2')
